WITH piligrim_dest_list AS ( SELECT DISTINCT dest_id FROM ( VALUES (70346),(808),(83409),(216354),(1585),(217362),(975),(759),(216346),(65815), (247),(307614),(289873),(76480),(204358),(298723),(82558),(75103),(517), (265316),(231),(1529),(879),(217335),(1242),(71642),(93968),(74124),(142), (636),(1136),(520),(669),(1061),(77167),(275),(69526),(802),(196),(1528), (77530),(200347),(305974),(68747),(735),(84848),(197504),(216551),(68705), (1343),(80438),(427),(77687),(73533),(196096),(202212),(711),(78796),(489), (747),(93580),(466),(77705),(68871),(1148),(1459),(361),(471),(70983), (81826),(501),(987),(93189),(76187),(196752),(84832),(74690),(1219), (94515),(1007),(65805),(496),(194482),(94509),(198868),(842),(69475), (74130),(215191),(84310),(1496),(403),(1141),(189),(133),(177),(1351), (70628),(74708),(66007),(198750),(663),(94877),(71756),(1128),(293),(534), (77093),(154),(1001),(70030),(576),(70429),(217),(960),(196420),(134), (205655),(94782),(300439) ) AS x(dest_id) ), srp_base AS ( SELECT DISTINCT date_format(at_timezone(s.__time, 'Asia/Kolkata'), '%Y-%b') AS month_period, os, channel, rb_user_id srprbuserid FROM "user_interaction"."search_route_details" s INNER JOIN piligrim_dest_list p ON s.src_id =p.dest_id OR s.dest_id = p.dest_id WHERE __time >= TIMESTAMP '2025-12-31 18:30:00' AND __time < TIMESTAMP '2026-01-31 18:30:00' AND channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND UPPER(user_type) = 'RETURNING' AND country = 'IND' ), confirm AS ( SELECT DISTINCT rb_user_id AS confirmuserid, CASE WHEN c.src_id IN (SELECT DISTINCT dest_id FROM piligrim_dest_list) OR c.dest_id IN (SELECT DISTINCT dest_id FROM piligrim_dest_list) THEN 1 ELSE 0 END AS pilgrim_transacted_user, CASE WHEN c.src_id NOT IN (SELECT DISTINCT dest_id FROM piligrim_dest_list) AND c.dest_id NOT IN (SELECT DISTINCT dest_id FROM piligrim_dest_list) THEN 1 ELSE 0 END AS non_pilgrim_transacted_user FROM "user_interaction"."confirm_order_details" c WHERE __time >= TIMESTAMP '2025-10-31 18:30:00' AND __time < TIMESTAMP '2026-01-31 18:30:00' AND channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND country = 'IND' AND status = 200 AND tin IS NOT NULL AND tin <> '' AND tin <> 'null' ) SELECT COUNT(DISTINCT s.srprbuserid) pilgrim_searched_users, COUNT(DISTINCT c.confirmuserid) overall_confirm_users, COUNT(DISTINCT CASE WHEN c.pilgrim_transacted_user = 0 THEN c.confirmuserid END) AS pure_non_pilgrim_transacted_users, COUNT(DISTINCT CASE WHEN c.non_pilgrim_transacted_user = 0 THEN c.confirmuserid END) AS pure_pilgrim_transacted_users FROM srp_base s LEFT JOIN confirm c ON c.confirmuserid = s.srprbuserid
